// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address player, uint256 sent) public {
        vm.assume(player != address(0));
        vm.assume(player != address(this));

        uint256 amount = bound(sent, 0, 100);

        vm.deal(player, amount + 1);

        bool ok;
        vm.prank(player);
        try c.play{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || amount == 10);
    }
}
